1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Pulsing Circle</title>
7	  <style>
8	    :root {
9	      --circle-hue: #8ec5ff;
10	      --circle-core: #4a7dd9;
11	      --circle-shadow: #1f3a75;
12	      --cycle: 2.5s;
13	    }
14	    * {
15	      margin: 0;
16	      padding: 0;
17	      box-sizing: border-box;
18	    }
19	    body {
20	      width: 100vw;
21	      height: 100vh;
22	      display: flex;
23	      justify-content: center;
24	      align-items: center;
25	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
26	      overflow: hidden;
27	    }
28	    svg {
29	      width: min(400px, 80vmin);
30	      height: min(400px, 80vmin);
31	      overflow: visible;
32	    }
33	    .ambient {
34	      fill: var(--circle-hue);
35	      opacity: 0.12;
36	      filter: blur(30px);
37	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
38	      transform-origin: 200px 200px;
39	    }
40	    .core {
41	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
42	      transform-origin: 200px 200px;
43	      filter: url(#glow);
44	      will-change: transform, opacity;
45	    }
46	    .highlight {
47	      fill: url(#highlightGradient);
48	      transform-origin: 200px 200px;
49	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
50	      pointer-events: none;
51	    }
52	    .ring {
53	      fill: none;
54	      stroke: var(--circle-hue);
55	      stroke-width: 2.5;
56	      transform-origin: 200px 200px;
57	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
58	      will-change: transform, opacity, stroke-width;
59	    }
60	    .ring--delay-1 {
61	      animation-delay: calc(var(--cycle) / 3);
62	    }
63	    .ring--delay-2 {
64	      animation-delay: calc(var(--cycle) / 3 * 2);
65	    }
66	    @keyframes pulse {
67	      0%, 100% {
68	        transform: scale(1);
69	        opacity: 0.9;
70	      }
71	      50% {
72	        transform: scale(1.05);
73	        opacity: 1;
74	      }
75	    }
76	    @keyframes breathe {
77	      0%, 100% {
78	        transform: scale(0.95);
79	        opacity: 0.1;
80	      }
81	      50% {
82	        transform: scale(1.1);
83	        opacity: 0.18;
84	      }
85	    }
86	    @keyframes ripple {
87	      0% {
88	        transform: scale(1);
89	        opacity: 0.6;
90	        stroke-width: 2.5;
91	      }
92	      100% {
93	        transform: scale(1.35);
94	        opacity: 0;
95	        stroke-width: 0.5;
96	      }
97	    }
98	    @media (prefers-reduced-motion: reduce) {
99	      .core, .ring, .ambient, .highlight {
100	        animation: none;
101	      }
102	      .ring {
103	        opacity: 0.35;
104	      }
105	      .ambient {
106	        opacity: 0.12;
107	      }
108	    }
109	  </style>
110	</head>
111	<body>
112	  <svg id="ae683f770" viewBox="0 0 400 400" role="img" aria-label="Pulsing blue circle animation">
113	    <defs>
114	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
115	        <stop offset="0%" stop-color="#8ec5ff"/>
116	        <stop offset="55%" stop-color="#4a7dd9"/>
117	        <stop offset="100%" stop-color="#1f3a75"/>
118	      </radialGradient>
119	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
120	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
121	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
122	      </radialGradient>
123	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
124	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
125	        <feColorMatrix in="blur" type="matrix"
126	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
127	        <feMerge>
128	          <feMergeNode in="tintedBlur"/>
129	          <feMergeNode in="SourceGraphic"/>
130	        </feMerge>
131	      </filter>
132	    </defs>
133	    <circle class="ambient" cx="200" cy="200" r="160"/>
134	    <circle class="ring" cx="200" cy="200" r="140"/>
135	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
136	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
137	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
138	    <circle class="highlight" cx="200" cy="200" r="140"/>
139	  </svg>
140	</body>
141	</html>
